local function playSoundRepeatedly()
	local soundId = "rbxassetid://18980441222"
	
	-- إنشاء Sound في SoundService
	local sound = Instance.new("Sound", SoundService)
	sound.SoundId = soundId
	sound.Volume = 1
	sound.PlayOnRemove = false
	
	-- تشغيل الصوت بشكل متكرر
	local startTime = tick()
	local soundConnection
	
	local function playLoop()
		if tick() - startTime >= 10 then
			-- إيقاف التكرار بعد 10 ثواني
			if soundConnection then
				soundConnection:Disconnect()
			end
			sound:Destroy()
			return
		end
		
		-- تشغيل الصوت
		local newSound = sound:Clone()
		newSound.Parent = SoundService
		newSound:Play()
		
		-- حذف الصوت بعد انتهائه
		newSound.Ended:Connect(function()
			newSound:Destroy()
		end)
	end
	
	-- تشغيل الصوت كل 0.5 ثانية
	soundConnection = RunService.Heartbeat:Connect(function()
		if tick() - startTime >= 10 then
			soundConnection:Disconnect()
			sound:Destroy()
			return
		end
		
		-- تشغيل الصوت كل 0.5 ثانية
		if (tick() - startTime) % 0.5 < 0.1 then
			local newSound = sound:Clone()
			newSound.Parent = SoundService
			newSound:Play()
			
			newSound.Ended:Connect(function()
				newSound:Destroy()
			end)
		end
	end)
	
	-- تشغيل الصوت فوراً عند البدء
	local firstSound = sound:Clone()
	firstSound.Parent = SoundService
	firstSound:Play()
	firstSound.Ended:Connect(function()
		firstSound:Destroy()
	end)
	
	-- إيقاف الصوت بعد 10 ثواني
	task.delay(10, function()
		if soundConnection then
			soundConnection:Disconnect()
		end
		sound:Destroy()
	end)
end

